/** One type-surface member. */
export type TypeMember =
    /** Named field. */
    | {
          readonly kind: "field";
          readonly key: Key;
          readonly declaredType?: LocalNodeId;
          readonly isStatic: boolean;
          readonly isOptional: boolean;
          readonly isReadonly: boolean;
      }
    /** Named method. */
    | {
          readonly kind: "method";
          readonly key: Key;
          readonly signature: FunctionSignature;
          readonly body?: LocalNodeId;
          readonly isStatic: boolean;
          readonly isOptional: boolean;
      }
    /** Call signature declaration. */
    | {
          readonly kind: "callSignature";
          /** The call signature function type expression. */
          readonly signature: FunctionTypeExpression;
      }
    /** Construct signature declaration. */
    | {
          readonly kind: "constructSignature";
          readonly signature: ConstructorType;
      }
    /** Index signature. */
    | {
          readonly kind: "indexSignature";
          readonly name: StringId;
          readonly keyType: LocalNodeId;
          readonly valueType: LocalNodeId;
          readonly isOptional: boolean;
          readonly isReadonly: boolean;
      }
    /** Associated type requirement or definition. */
    | {
          readonly kind: "associatedType";
          readonly name: StringId;
          readonly genericParameters: ReadonlyArray<LocalNodeId>;
          readonly whereClauses: ReadonlyArray<LocalNodeId>;
          readonly constraint?: LocalNodeId;
          readonly value?: LocalNodeId;
          readonly isAbstract: boolean;
          readonly isOverride: boolean;
      }
    /** Associated compile-time constant requirement or definition. */
    | {
          readonly kind: "associatedConst";
          readonly name: StringId;
          readonly declaredType?: LocalNodeId;
          readonly value?: LocalNodeId;
          readonly isAbstract: boolean;
          readonly isOverride: boolean;
      }
    /** Malformed type member slot. */
    | {
          readonly kind: "error";
      }
;

export const TypeMember = {
    /** Named field. */
    field(key: Key, declaredType: LocalNodeId | undefined, isStatic: boolean, isOptional: boolean, isReadonly: boolean): TypeMember {
        return { kind: "field", key, declaredType, isStatic, isOptional, isReadonly };
    },

    /** Named method. */
    method(key: Key, signature: FunctionSignature, body: LocalNodeId | undefined, isStatic: boolean, isOptional: boolean): TypeMember {
        return { kind: "method", key, signature, body, isStatic, isOptional };
    },

    /** Call signature declaration. */
    callSignature(signature: FunctionTypeExpression): TypeMember {
        return { kind: "callSignature", signature };
    },

    /** Construct signature declaration. */
    constructSignature(signature: ConstructorType): TypeMember {
        return { kind: "constructSignature", signature };
    },

    /** Index signature. */
    indexSignature(name: StringId, keyType: LocalNodeId, valueType: LocalNodeId, isOptional: boolean, isReadonly: boolean): TypeMember {
        return { kind: "indexSignature", name, keyType, valueType, isOptional, isReadonly };
    },

    /** Associated type requirement or definition. */
    associatedType(name: StringId, genericParameters: ReadonlyArray<LocalNodeId>, whereClauses: ReadonlyArray<LocalNodeId>, constraint: LocalNodeId | undefined, value: LocalNodeId | undefined, isAbstract: boolean, isOverride: boolean): TypeMember {
        return { kind: "associatedType", name, genericParameters, whereClauses, constraint, value, isAbstract, isOverride };
    },

    /** Associated compile-time constant requirement or definition. */
    associatedConst(name: StringId, declaredType: LocalNodeId | undefined, value: LocalNodeId | undefined, isAbstract: boolean, isOverride: boolean): TypeMember {
        return { kind: "associatedConst", name, declaredType, value, isAbstract, isOverride };
    },

    /** Malformed type member slot. */
    error(): TypeMember {
        return { kind: "error" };
    },

    /** Encode this value. */
    encode(writer: BinaryWriter, value: TypeMember): void {
        encodeTypeMember(writer, value);
    },

    /** Decode one TypeMember. */
    decode(reader: BinaryReader): TypeMember {
        return decodeTypeMember(reader);
    },

    /** Return this value as JSON. */
    toJson(value: TypeMember): Json {
        return toJsonTypeMember(value);
    },

    /** Return one TypeMember from one JSON value. */
    fromJson(value: Json): TypeMember {
        return fromJsonTypeMember(value);
    },
};

/** Encode one TypeMember. */
export function encodeTypeMember(writer: BinaryWriter, value: TypeMember): void {
    switch (value.kind) {
        case "field":
            writer.writeUnsigned(0);
            encodeKey(writer, value.key);
            writer.writeOption(value.declaredType, (value1) => {
                encodeLocalNodeId(writer, value1);
            });
            writer.writeBool(value.isStatic);
            writer.writeBool(value.isOptional);
            writer.writeBool(value.isReadonly);
            return;
        case "method":
            writer.writeUnsigned(1);
            encodeKey(writer, value.key);
            encodeFunctionSignature(writer, value.signature);
            writer.writeOption(value.body, (value2) => {
                encodeLocalNodeId(writer, value2);
            });
            writer.writeBool(value.isStatic);
            writer.writeBool(value.isOptional);
            return;
        case "callSignature":
            writer.writeUnsigned(2);
            encodeFunctionTypeExpression(writer, value.signature);
            return;
        case "constructSignature":
            writer.writeUnsigned(3);
            encodeConstructorType(writer, value.signature);
            return;
        case "indexSignature":
            writer.writeUnsigned(4);
            encodeStringId(writer, value.name);
            encodeLocalNodeId(writer, value.keyType);
            encodeLocalNodeId(writer, value.valueType);
            writer.writeBool(value.isOptional);
            writer.writeBool(value.isReadonly);
            return;
        case "associatedType":
            writer.writeUnsigned(5);
            encodeStringId(writer, value.name);
            writer.writeUnsigned(value.genericParameters.length);
            for (const item1 of value.genericParameters) {
                encodeLocalNodeId(writer, item1);
            }
            writer.writeUnsigned(value.whereClauses.length);
            for (const item2 of value.whereClauses) {
                encodeLocalNodeId(writer, item2);
            }
            writer.writeOption(value.constraint, (value3) => {
                encodeLocalNodeId(writer, value3);
            });
            writer.writeOption(value.value, (value4) => {
                encodeLocalNodeId(writer, value4);
            });
            writer.writeBool(value.isAbstract);
            writer.writeBool(value.isOverride);
            return;
        case "associatedConst":
            writer.writeUnsigned(6);
            encodeStringId(writer, value.name);
            writer.writeOption(value.declaredType, (value1) => {
                encodeLocalNodeId(writer, value1);
            });
            writer.writeOption(value.value, (value2) => {
                encodeLocalNodeId(writer, value2);
            });
            writer.writeBool(value.isAbstract);
            writer.writeBool(value.isOverride);
            return;
        case "error":
            writer.writeUnsigned(7);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one TypeMember. */
export function decodeTypeMember(reader: BinaryReader): TypeMember {
    const variant = reader.readNumber();

    switch (variant) {
        case 0: {
            const key = decodeKey(reader);
            const declaredType = reader.readOption(() => decodeLocalNodeId(reader));
            const isStatic = reader.readBool();
            const isOptional = reader.readBool();
            const isReadonly = reader.readBool();

            return {
                kind: "field",
                key,
                ...(declaredType === undefined ? {} : { declaredType }),
                isStatic,
                isOptional,
                isReadonly,
            };
        }
        case 1: {
            const key = decodeKey(reader);
            const signature = decodeFunctionSignature(reader);
            const body = reader.readOption(() => decodeLocalNodeId(reader));
            const isStatic = reader.readBool();
            const isOptional = reader.readBool();

            return {
                kind: "method",
                key,
                signature,
                ...(body === undefined ? {} : { body }),
                isStatic,
                isOptional,
            };
        }
        case 2: {
            const signature = decodeFunctionTypeExpression(reader);

            return {
                kind: "callSignature",
                signature,
            };
        }
        case 3: {
            const signature = decodeConstructorType(reader);

            return {
                kind: "constructSignature",
                signature,
            };
        }
        case 4: {
            const name = decodeStringId(reader);
            const keyType = decodeLocalNodeId(reader);
            const valueType = decodeLocalNodeId(reader);
            const isOptional = reader.readBool();
            const isReadonly = reader.readBool();

            return {
                kind: "indexSignature",
                name,
                keyType,
                valueType,
                isOptional,
                isReadonly,
            };
        }
        case 5: {
            const name = decodeStringId(reader);
            const genericParameters = (() => { const length1 = reader.readNumber(); const items1: Array<LocalNodeId> = []; for (let index = 0; index < length1; index += 1) { items1.push(decodeLocalNodeId(reader)); } return items1; })();
            const whereClauses = (() => { const length2 = reader.readNumber(); const items2: Array<LocalNodeId> = []; for (let index = 0; index < length2; index += 1) { items2.push(decodeLocalNodeId(reader)); } return items2; })();
            const constraint = reader.readOption(() => decodeLocalNodeId(reader));
            const value = reader.readOption(() => decodeLocalNodeId(reader));
            const isAbstract = reader.readBool();
            const isOverride = reader.readBool();

            return {
                kind: "associatedType",
                name,
                genericParameters,
                whereClauses,
                ...(constraint === undefined ? {} : { constraint }),
                ...(value === undefined ? {} : { value }),
                isAbstract,
                isOverride,
            };
        }
        case 6: {
            const name = decodeStringId(reader);
            const declaredType = reader.readOption(() => decodeLocalNodeId(reader));
            const value = reader.readOption(() => decodeLocalNodeId(reader));
            const isAbstract = reader.readBool();
            const isOverride = reader.readBool();

            return {
                kind: "associatedConst",
                name,
                ...(declaredType === undefined ? {} : { declaredType }),
                ...(value === undefined ? {} : { value }),
                isAbstract,
                isOverride,
            };
        }
        case 7: {
            return { kind: "error" };
        }
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one TypeMember. */
export function toJsonTypeMember(value: TypeMember): Json {
    switch (value.kind) {
        case "field":
            return {
                kind: "field",
                key: toJsonKey(value.key),
                ...(value.declaredType === undefined ? {} : { declaredType: toJsonLocalNodeId(value.declaredType) }),
                isStatic: value.isStatic,
                isOptional: value.isOptional,
                isReadonly: value.isReadonly,
            };
        case "method":
            return {
                kind: "method",
                key: toJsonKey(value.key),
                signature: toJsonFunctionSignature(value.signature),
                ...(value.body === undefined ? {} : { body: toJsonLocalNodeId(value.body) }),
                isStatic: value.isStatic,
                isOptional: value.isOptional,
            };
        case "callSignature":
            return {
                kind: "callSignature",
                signature: toJsonFunctionTypeExpression(value.signature),
            };
        case "constructSignature":
            return {
                kind: "constructSignature",
                signature: toJsonConstructorType(value.signature),
            };
        case "indexSignature":
            return {
                kind: "indexSignature",
                name: toJsonStringId(value.name),
                keyType: toJsonLocalNodeId(value.keyType),
                valueType: toJsonLocalNodeId(value.valueType),
                isOptional: value.isOptional,
                isReadonly: value.isReadonly,
            };
        case "associatedType":
            return {
                kind: "associatedType",
                name: toJsonStringId(value.name),
                genericParameters: value.genericParameters.map((item0) => toJsonLocalNodeId(item0)),
                whereClauses: value.whereClauses.map((item0) => toJsonLocalNodeId(item0)),
                ...(value.constraint === undefined ? {} : { constraint: toJsonLocalNodeId(value.constraint) }),
                ...(value.value === undefined ? {} : { value: toJsonLocalNodeId(value.value) }),
                isAbstract: value.isAbstract,
                isOverride: value.isOverride,
            };
        case "associatedConst":
            return {
                kind: "associatedConst",
                name: toJsonStringId(value.name),
                ...(value.declaredType === undefined ? {} : { declaredType: toJsonLocalNodeId(value.declaredType) }),
                ...(value.value === undefined ? {} : { value: toJsonLocalNodeId(value.value) }),
                isAbstract: value.isAbstract,
                isOverride: value.isOverride,
            };
        case "error":
            return {
                kind: "error",
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one TypeMember from one JSON value. */
export function fromJsonTypeMember(value: Json): TypeMember {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "field":
            return {
                kind,
                key: fromJsonKey(jsonField(object, "key")),
                declaredType: jsonOptional(object, "declaredType", (value) => fromJsonLocalNodeId(value)),
                isStatic: jsonBool(jsonField(object, "isStatic")),
                isOptional: jsonBool(jsonField(object, "isOptional")),
                isReadonly: jsonBool(jsonField(object, "isReadonly")),
            };
        case "method":
            return {
                kind,
                key: fromJsonKey(jsonField(object, "key")),
                signature: fromJsonFunctionSignature(jsonField(object, "signature")),
                body: jsonOptional(object, "body", (value) => fromJsonLocalNodeId(value)),
                isStatic: jsonBool(jsonField(object, "isStatic")),
                isOptional: jsonBool(jsonField(object, "isOptional")),
            };
        case "callSignature":
            return {
                kind,
                signature: fromJsonFunctionTypeExpression(jsonField(object, "signature")),
            };
        case "constructSignature":
            return {
                kind,
                signature: fromJsonConstructorType(jsonField(object, "signature")),
            };
        case "indexSignature":
            return {
                kind,
                name: fromJsonStringId(jsonField(object, "name")),
                keyType: fromJsonLocalNodeId(jsonField(object, "keyType")),
                valueType: fromJsonLocalNodeId(jsonField(object, "valueType")),
                isOptional: jsonBool(jsonField(object, "isOptional")),
                isReadonly: jsonBool(jsonField(object, "isReadonly")),
            };
        case "associatedType":
            return {
                kind,
                name: fromJsonStringId(jsonField(object, "name")),
                genericParameters: jsonArray(jsonField(object, "genericParameters")).map((item0) => fromJsonLocalNodeId(item0)),
                whereClauses: jsonArray(jsonField(object, "whereClauses")).map((item0) => fromJsonLocalNodeId(item0)),
                constraint: jsonOptional(object, "constraint", (value) => fromJsonLocalNodeId(value)),
                value: jsonOptional(object, "value", (value) => fromJsonLocalNodeId(value)),
                isAbstract: jsonBool(jsonField(object, "isAbstract")),
                isOverride: jsonBool(jsonField(object, "isOverride")),
            };
        case "associatedConst":
            return {
                kind,
                name: fromJsonStringId(jsonField(object, "name")),
                declaredType: jsonOptional(object, "declaredType", (value) => fromJsonLocalNodeId(value)),
                value: jsonOptional(object, "value", (value) => fromJsonLocalNodeId(value)),
                isAbstract: jsonBool(jsonField(object, "isAbstract")),
                isOverride: jsonBool(jsonField(object, "isOverride")),
            };
        case "error":
            return {
                kind,
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}

/** A mapped type parameter. */
export type TypeMappedParameter = {
    /** The parameter name. */
    readonly name: StringId;
    /** The source type iterated by `in`. */
    readonly sourceType: LocalNodeId;
    /** The optional key remap. */
    readonly keyRemap?: LocalNodeId;
};

export const TypeMappedParameter = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: TypeMappedParameter): void {
        encodeTypeMappedParameter(writer, value);
    },

    /** Decode one TypeMappedParameter. */
    decode(reader: BinaryReader): TypeMappedParameter {
        return decodeTypeMappedParameter(reader);
    },

    /** Return this value as JSON. */
    toJson(value: TypeMappedParameter): Json {
        return toJsonTypeMappedParameter(value);
    },

    /** Return one TypeMappedParameter from one JSON value. */
    fromJson(value: Json): TypeMappedParameter {
        return fromJsonTypeMappedParameter(value);
    },
};

/** Encode one TypeMappedParameter. */
export function encodeTypeMappedParameter(writer: BinaryWriter, value: TypeMappedParameter): void {
    encodeStringId(writer, value.name);
    encodeLocalNodeId(writer, value.sourceType);
    writer.writeOption(value.keyRemap, (value2) => {
        encodeLocalNodeId(writer, value2);
    });
}

/** Decode one TypeMappedParameter. */
export function decodeTypeMappedParameter(reader: BinaryReader): TypeMappedParameter {
    const name = decodeStringId(reader);
    const sourceType = decodeLocalNodeId(reader);
    const keyRemap = reader.readOption(() => decodeLocalNodeId(reader));

    return {
        name,
        sourceType,
        ...(keyRemap === undefined ? {} : { keyRemap }),
    };
}

/** Return one JSON value for one TypeMappedParameter. */
export function toJsonTypeMappedParameter(value: TypeMappedParameter): Json {
    return {
        name: toJsonStringId(value.name),
        sourceType: toJsonLocalNodeId(value.sourceType),
        ...(value.keyRemap === undefined ? {} : { keyRemap: toJsonLocalNodeId(value.keyRemap) }),
    };
}

/** Return one TypeMappedParameter from one JSON value. */
export function fromJsonTypeMappedParameter(value: Json): TypeMappedParameter {
    const object = jsonObject(value);

    return {
        name: fromJsonStringId(jsonField(object, "name")),
        sourceType: fromJsonLocalNodeId(jsonField(object, "sourceType")),
        keyRemap: jsonOptional(object, "keyRemap", (value) => fromJsonLocalNodeId(value)),
    };
}
